export const SLOT_LABELS={core:'Núcleo',arm:'Braço',shield:'Escudo',booster:'Propulsor',sensor:'Sensor'};
export function robotSlots(info){return info.contract?.slots||info.slots||['core','arm','shield'];}
export function createEquipmentView(env){const {core:C,escape:esc,icon:I,button:btn,partArt,modal}=env;
 function slots(info){return `<div class="robot-equipment-slots">${robotSlots(info).map(slot=>{const part=info.equipment.find(p=>p.slot===slot);return `<article class="equipment-slot ${part?'filled':'empty'}"><div class="slot-portrait">${part?partArt(part):I(slot==='core'?'core':slot==='arm'?'arm':slot==='shield'?'shield':'bolt')}</div><div><span>${SLOT_LABELS[slot]||esc(slot)}</span><b>${part?esc(part.name):'Espaço disponível'}</b><small>${part?'NV. '+part.equipmentLevel+' · +'+part.production+'% produção':'Escolha uma peça compatível'}</small></div><div class="slot-actions">${btn(I('plus')+(part?' Trocar':' Adicionar'),'slot-equip',`data-id="${info.uid}" data-slot="${esc(slot)}"`,'secondary')}${part?btn(I('bolt')+' Evoluir · '+(env.getState().settings.levelCost*part.equipmentLevel)+' RC','slot-upgrade',`data-id="${part.uid}" data-robot="${info.uid}"`,'primary'):''}</div></article>`;}).join('')}</div>`;}
 function open(uid,slot){const s=env.getState(),robot=s.robots.find(r=>r.uid===uid);if(!robot)return;const info=C.robotInfo(s,robot);if(!robotSlots(info).includes(slot))throw new Error('Este espaço não está disponível no robô.');
  const compatible=s.parts.filter(p=>p.slot===slot&&p.compatible.includes(info.type)),owned=s.inventory.filter(item=>compatible.some(p=>p.id===item.partId));
  modal(`<span class="eyebrow">${esc(info.name)} · ${SLOT_LABELS[slot]||esc(slot)}</span><h2 id="modal-title">Monte sua próxima evolução.</h2><p>Escolha uma peça do inventário ou adquira e equipe no mesmo passo. A peça anterior volta ao inventário.</p><div class="section-title"><h3>Seu inventário</h3></div><div class="equipment-selection">${owned.map(item=>{const p=s.parts.find(p=>p.id===item.partId),busy=item.equippedOn&&item.equippedOn!==uid;return `<article>${partArt(p)}<div><h3>${esc(p.name)}</h3><p>NV. ${item.level} · +${p.production}% produção</p><small>${busy?'Equipada em outro robô':item.equippedOn===uid?'Já está equipada aqui':'Disponível'}</small></div>${btn('Equipar','slot-equip-owned',`data-id="${item.uid}" data-robot="${uid}" ${busy||item.equippedOn===uid?'disabled':''}`,'secondary')}</article>`;}).join('')||'<p class="subtle">Nenhuma peça compatível neste espaço.</p>'}</div><div class="section-title"><h3>Peças compatíveis da oficina</h3></div><div class="equipment-selection">${compatible.map(p=>`<article>${partArt(p)}<div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><small>+${p.production}% produção · +${p.attack} ataque · +${p.defense} defesa</small><b>${p.price} ${p.currency}</b></div>${btn('Adquirir e equipar','slot-buy',`data-id="${p.id}" data-robot="${uid}"`,'primary')}</article>`).join('')}</div>${btn('Voltar ao robô','robot-detail',`data-id="${uid}"`,'secondary wide')}`,'equipment-selection-modal large');
 }
 return {slots,open};
}
